Let me create a standalone test program. I'll create a minimal version that includes the demangle code directly:

<｜｜DSML｜｜_command>
<parameter=command>cat > /workspace/test_demangle.cc << 'EOF'
#include <cstdio>
#include <cstring>
#include <cstdlib>

#define _START_GOOGLE_NAMESPACE_ namespace google {
#define _END_GOOGLE_NAMESPACE_ }
#define GLOG_EXPORT

#include "/workspace/repo-vul/src-vul/glog/src/demangle.cc"

int main(int argc, char** argv) {
  if (argc < 2) return 1;
  FILE* f = fopen(argv[1], "rb");
  if (!f) return 1;
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (size >= 4095) return 0;
  char* data = (char*)malloc(size);
  fread(data, 1, size, f);
  fclose(f);

  char Buffer[size + 1];
  std::memcpy(Buffer, data, size);
  Buffer[size] = 0;
  char demangled[4096];
  google::Demangle(Buffer, demangled, size);
  free(data);
  return 0;
}
EOF
